/* ============================================================
   Two full 65-question practice exams, weighted to match the
   real AIF-C01 domain proportions: 13 / 16 / 18 / 9 / 9
   ============================================================ */

const D1 = "Domain 1 · Fundamentals of AI & ML";
const D2 = "Domain 2 · Fundamentals of Generative AI";
const D3 = "Domain 3 · Applications of Foundation Models";
const D4 = "Domain 4 · Guidelines for Responsible AI";
const D5 = "Domain 5 · Security, Compliance & Governance";

const EXAM_DATA = { exam1: { name: "Practice Exam 1", questions: [] }, exam2: { name: "Practice Exam 2", questions: [] } };

EXAM_DATA.exam1.questions.push(
  {domain:D1, q:"A retailer wants a system that writes original product descriptions from a list of features. Which category best describes this capability?", options:["Classical machine learning","Generative AI","Reinforcement learning only","Rule-based automation"], correct:1,
   explain:"Producing original content (new descriptions) rather than predicting a label is the defining trait of generative AI."},
  {domain:D1, q:"A model trained to detect manufacturing defects performs at 97% accuracy on training images but only 68% on new images from the factory floor. What's the most likely cause?", options:["Underfitting","Overfitting","Insufficient compute at inference time","The model needs a lower learning rate only"], correct:1,
   explain:"A large training-to-test performance gap, with strong training performance, is the classic signature of overfitting."},
  {domain:D1, q:"A team wants to group customers into segments based on purchasing behavior, with no predefined categories. Which ML paradigm fits?", options:["Supervised learning","Unsupervised learning","Reinforcement learning","Semi-supervised learning"], correct:1,
   explain:"Finding structure in unlabeled data — like customer segments with no predefined categories — is unsupervised learning."},
  {domain:D1, q:"A robotics team trains an agent to complete a warehouse-picking task by rewarding successful picks and penalizing dropped items. Which paradigm is this?", options:["Supervised learning","Unsupervised learning","Reinforcement learning","Deep learning exclusively"], correct:2,
   explain:"Learning through reward and penalty signals from interacting with an environment is reinforcement learning."},
  {domain:D1, q:"A bank's fraud model must minimize missed fraud cases even if that means more false alarms for analysts to review. Which metric should be prioritized?", options:["Precision","Recall","Plain accuracy","R-squared"], correct:1,
   explain:"When missing true positives (fraud) is costlier than false alarms, recall — how many actual positives were caught — is the metric to prioritize."},
  {domain:D1, q:"A spam classifier must avoid flagging legitimate emails as spam, even if it lets a few spam emails through. Which metric should be prioritized?", options:["Precision","Recall","AUC-ROC alone","RMSE"], correct:0,
   explain:"When false positives (legitimate emails wrongly flagged) are the costly error, precision — how many predicted positives were actually correct — is the priority."},
  {domain:D1, q:"A regression model predicting house prices needs an error metric. Which is appropriate?", options:["F1 score","Precision","RMSE","AUC-ROC"], correct:2,
   explain:"RMSE (root mean squared error) measures the magnitude of prediction error for continuous outputs like price — a regression task, not classification."},
  {domain:D1, q:"A company needs to moderate user-uploaded images for inappropriate content, with no ML team on staff. What's the best-fit AWS service?", options:["Amazon SageMaker custom model","Amazon Rekognition","Amazon Comprehend","Amazon Kendra"], correct:1,
   explain:"Rekognition is a pre-built service for image and video analysis, including content moderation, requiring no ML expertise or custom training."},
  {domain:D1, q:"A call center wants to automatically convert recorded customer calls into searchable text transcripts. Which service fits?", options:["Amazon Polly","Amazon Transcribe","Amazon Translate","Amazon Lex"], correct:1,
   explain:"Amazon Transcribe performs speech-to-text conversion, the exact requirement for turning recorded calls into text transcripts."},
  {domain:D1, q:"A company has a large proprietary dataset and a task that no existing AWS pre-built AI service addresses. What's the appropriate starting point?", options:["Amazon Comprehend","Amazon SageMaker","Amazon Polly","Amazon Translate"], correct:1,
   explain:"SageMaker is the platform for building, training, and deploying fully custom models — the right call for a genuinely proprietary task."},
  {domain:D1, q:"Which best describes the relationship between deep learning and generative AI?", options:["They are unrelated fields","Generative AI is a subset of deep learning","Deep learning is a subset of generative AI","They are always the same thing"], correct:1,
   explain:"Generative AI is a further subset of deep learning: deep learning models specifically built to produce new content."},
  {domain:D1, q:"A model performs poorly on both training data and new data alike. What does this suggest?", options:["Overfitting","Underfitting","Perfect generalization","Insufficient regularization is the only possible cause"], correct:1,
   explain:"Poor performance on training data itself indicates the model is too simple to capture the underlying pattern — underfitting, or high bias."},
  {domain:D1, q:"An enterprise search tool needs to let employees semantically search across thousands of internal documents. Which AWS service is purpose-built for this?", options:["Amazon Kendra","Amazon Polly","Amazon Forecast","Amazon Personalize"], correct:0,
   explain:"Amazon Kendra is AWS's enterprise semantic search service, built specifically for searching across large document sets."}
);

EXAM_DATA.exam1.questions.push(
  {domain:D2, q:"What best defines a foundation model?", options:["A model trained narrowly for a single task with labeled data", "A model pre-trained broadly on large-scale data and adaptable to many downstream tasks", "Any model deployed on Amazon SageMaker", "A model that only performs classification"], correct:1,
   explain:"Foundation models are pre-trained broadly on large, mostly unlabeled datasets, making them adaptable to many downstream tasks — unlike narrow, task-specific models."},
  {domain:D2, q:"What mechanism allows a transformer to weigh the relevance of every other token when processing a given token?", options:["Convolution","Self-attention","Gradient descent","Tokenization"], correct:1,
   explain:"Self-attention is the core transformer mechanism that lets the model weigh relationships between all tokens in a sequence simultaneously."},
  {domain:D2, q:"Why do transformers generally train faster at scale than older RNN architectures?", options:["They require less data","They process sequences in parallel rather than one token at a time","They don't use neural networks","They only work on short sequences"], correct:1,
   explain:"Self-attention lets transformers process an entire sequence in parallel, unlike RNNs, which process tokens sequentially — a major factor in their scalability."},
  {domain:D2, q:"A generation task requires the most deterministic, repeatable output possible. Which sampling parameter setting is most appropriate?", options:["High temperature","Low temperature","High Top P only","Unlimited max tokens"], correct:1,
   explain:"Low temperature sharpens the probability distribution toward the highest-probability tokens, producing more deterministic, repeatable output."},
  {domain:D2, q:"Top K is set to 5 for a vocabulary of 50,000 tokens. How many tokens are eligible to be sampled, regardless of temperature?", options:["50,000","Exactly 5","A number that varies based on temperature","It depends on Top P"], correct:1,
   explain:"Top K is a hard, fixed-count filter — exactly K tokens survive, applied before temperature has any influence on the reshaped distribution."},
  {domain:D2, q:"At Top P = 0.9, why might the number of eligible tokens vary significantly between two different prompts?", options:["Top P always keeps exactly the same number of tokens","The cumulative probability threshold is reached by a different number of tokens depending on how concentrated each distribution is","Top P is identical to Top K","Temperature overrides Top P in all cases"], correct:1,
   explain:"Top P's candidate count depends on the shape of the probability distribution for each specific prediction — a flatter distribution needs more tokens to reach the threshold than a sharply peaked one."},
  {domain:D2, q:"What is a token, in the context of a large language model?", options:["A billing unit only, unrelated to model processing","A sub-word unit of text the model operates on","A single character always","A complete sentence"], correct:1,
   explain:"Tokens are sub-word units of text — roughly three-quarters of a word on average in English — that the model actually processes."},
  {domain:D2, q:"What does an embedding represent?", options:["A compressed version of the model's weights", "A numeric vector positioning text so that similar meanings are close together in vector space", "A hard rule for filtering unsafe content", "The exact token count of a prompt"], correct:1,
   explain:"An embedding is a numeric vector representation positioned so that semantically similar text ends up close together — the basis for semantic search."},
  {domain:D2, q:"A model's context window is 4,000 tokens. A prompt uses 3,500 input tokens. What is the maximum possible output length?", options:["4,000 tokens","500 tokens","3,500 tokens","Unlimited, context window only limits input"], correct:1,
   explain:"The context window is a ceiling on input plus output combined. With 3,500 used by input, at most 500 tokens remain for output."},
  {domain:D2, q:"A team wants to evaluate machine-translated text against reference translations. Which metric is purpose-built for this?", options:["ROUGE","BLEU","F1 score","AUC-ROC"], correct:1,
   explain:"BLEU is precision-oriented with a brevity penalty and was specifically designed for evaluating machine translation."},
  {domain:D2, q:"Which evaluation metric compares generated and reference text using contextual embeddings rather than exact word overlap?", options:["BLEU","ROUGE","BERTScore","Accuracy"], correct:2,
   explain:"BERTScore uses contextual embeddings to catch semantic similarity, including paraphrases, that exact n-gram overlap metrics like ROUGE and BLEU miss."},
  {domain:D2, q:"What does RLHF stand for, and what is it used for?", options:["Random Layer Hyperparameter Fitting; model compression","Reinforcement Learning from Human Feedback; aligning model behavior using human preference rankings","Rapid Learning for High-throughput Fine-tuning; speeding up training only","Reduced Latency Hosting Framework; deployment infrastructure"], correct:1,
   explain:"RLHF trains a reward model from human preference rankings of model outputs, then uses that signal to further align the LLM's behavior."},
  {domain:D2, q:"What is Amazon Bedrock's primary value proposition?", options:["It trains foundation models from scratch for you","It provides a single API to access foundation models from multiple providers without managing infrastructure","It is exclusively for image generation","It replaces the need for prompt engineering"], correct:1,
   explain:"Bedrock offers a single managed API across multiple foundation model providers, letting you swap models without rewriting your application or managing servers."},
  {domain:D2, q:"A company needs predictable performance for a high-volume, steady production workload on Bedrock. Which pricing option fits best?", options:["On-demand pricing","Provisioned Throughput","Spot pricing","Free tier only"], correct:1,
   explain:"Provisioned Throughput is designed for predictable, high-volume workloads, as opposed to on-demand pricing which suits variable, unpredictable usage."},
  {domain:D2, q:"Which of these is a genuine disadvantage or risk of generative AI, as opposed to traditional software?", options:["It can never process text","Hallucination — confident but fabricated output","It cannot be deployed on AWS","It requires no data at all"], correct:1,
   explain:"Hallucination — the model producing confident but fabricated content — is a well-documented risk specific to generative AI systems."},
  {domain:D2, q:"What is the primary difference between a diffusion model and a large language model, in terms of typical use?", options:["Diffusion models are typically used for image generation; LLMs for text","There is no meaningful difference","Diffusion models cannot be foundation models","LLMs cannot generate any structured output"], correct:0,
   explain:"Diffusion models are commonly used for image generation, while large language models specialize in text — both are types of foundation models."}
);

EXAM_DATA.exam1.questions.push(
  {domain:D3, q:"A prompt includes three examples of the desired input/output format before the actual task. What is this technique called?", options:["Zero-shot prompting","Few-shot prompting","Chain-of-thought prompting","Negative prompting"], correct:1,
   explain:"Providing a handful of input/output examples in the prompt to demonstrate a pattern is few-shot prompting."},
  {domain:D3, q:"A prompt asks the model to 'think through this step by step before giving your final answer.' What technique is this, and what does it typically improve?", options:["Few-shot prompting; output length","Chain-of-thought prompting; multi-step reasoning performance","Negative prompting; safety filtering","Zero-shot prompting; token efficiency"], correct:1,
   explain:"Chain-of-thought prompting asks the model to reason step by step, which measurably improves performance on multi-step reasoning tasks."},
  {domain:D3, q:"A company wants a chatbot's answers to always reflect this quarter's product catalog, which updates monthly. Which approach best fits, and why?", options:["Fine-tune monthly, because it is the cheapest option","RAG against a live catalog data source, because it reflects current data without retraining","Increase the temperature setting","Use only zero-shot prompting"], correct:1,
   explain:"RAG retrieves current information at query time, staying current without the cost and delay of retraining a model every month."},
  {domain:D3, q:"A team retrains a foundation model on their proprietary legal documents so the model's weights directly encode that knowledge. What is this technique, precisely?", options:["RAG, because the model 'knows' the documents afterward","Fine-tuning, because the data was incorporated through additional training rather than retrieved at query time","Prompt engineering","Chain-of-thought reasoning"], correct:1,
   explain:"The distinguishing test is when the data is incorporated. Retraining on the documents is fine-tuning, regardless of how the end result appears to a user."},
  {domain:D3, q:"In the RAG query-time flow, what happens immediately before a similarity search runs against the vector store?", options:["The LLM generates a final answer","The user's query is embedded into a vector","Bedrock Guardrails filters the response","The model is fine-tuned"], correct:1,
   explain:"The query must be embedded into a vector before a similarity search can compare it against the embedded chunks in the vector store."},
  {domain:D3, q:"Which RAG knowledge base pattern combines keyword and vector search, with results re-ranked afterward?", options:["Traditional keyword search","Vector database search","Hybrid search","Graph RAG"], correct:2,
   explain:"Hybrid search combines keyword and vector scores, often via reciprocal rank fusion, then re-ranks the combined results."},
  {domain:D3, q:"Which Bedrock Knowledge Bases API performs retrieval, prompt augmentation, and the LLM call in a single step?", options:["Retrieve","RetrieveAndGenerate","InvokeModel","Converse"], correct:1,
   explain:"RetrieveAndGenerate handles retrieval, prompt augmentation, and the LLM call together, returning a final answer rather than raw chunks."},
  {domain:D3, q:"A team uses AWS Bedrock Managed Knowledge Bases instead of self-managing a vector store. What is the primary trade-off?", options:["No trade-off exists","Lower operational complexity and cost, in exchange for less fine-grained control over chunking and ranking", "It eliminates the need for embeddings entirely", "It only works with keyword search"], correct:1,
   explain:"Managed Knowledge Bases trade fine-grained control over chunking strategy and ranking behavior for operational simplicity and lower idle cost."},
  {domain:D3, q:"A RAG pipeline uses very small, fixed-size chunks with heavy overlap. What is the most likely downside?", options:["Chunks retrieve very imprecisely","Chunks may lack enough surrounding context even when retrieval itself is accurate","Embedding cost drops to zero","The vector database becomes unnecessary"], correct:1,
   explain:"Very small chunks can retrieve precisely but carry too little context individually, which can hurt the quality of the generated answer even with accurate retrieval."},
  {domain:D3, q:"What does the 'lost in the middle' finding describe?", options:["Models attend more reliably to the start and end of a long context than to content buried in the middle","Models always ignore the first half of any prompt","Longer prompts always produce better answers","Context window size has no effect on model attention"], correct:0,
   explain:"The 'lost in the middle' effect describes LLMs attending more reliably to content at the start and end of a long context than to content in the middle."},
  {domain:D3, q:"Why is RAG evaluation typically split into two separate layers?", options:["Because retrieval quality and generation faithfulness are separate failure surfaces that require different fixes","Because AWS requires two separate services for RAG","Because there is only one possible failure mode in RAG","Because chunking and embedding are the same process"], correct:0,
   explain:"Bad retrieval and unfaithful generation are distinct problems: good retrieval doesn't guarantee a faithful answer, and a strong LLM can't compensate for irrelevant retrieved content."},
  {domain:D3, q:"A Bedrock Agent needs to actually cancel a customer's order, not just describe how to do it. What capability does this require?", options:["A larger context window only","The ability to call a real API or Lambda function to take action","A Knowledge Base alone, with no other components","Increasing the temperature parameter"], correct:1,
   explain:"What separates an agent from a plain chatbot is the ability to call APIs or Lambda functions to take real action, not just generate text."},
  {domain:D3, q:"Where do Bedrock Guardrails apply their content filtering and PII redaction checks?", options:["Only during model training","At runtime, independent of which underlying foundation model is used","Only inside the vector database","Only during the fine-tuning process"], correct:1,
   explain:"Guardrails apply runtime checks — denied topics, content filtering, PII redaction, grounding checks — independent of the specific model generating the response."},
  {domain:D3, q:"A live customer-support chat application prioritizes fast responses above nearly everything else. Which model-selection criterion should be weighted most heavily?", options:["Context window size","Latency","Modality","Fine-tuning support"], correct:1,
   explain:"For a real-time interactive interface, response speed (latency) is usually the dominant constraint on model choice."},
  {domain:D3, q:"A task requires the model to analyze audio recordings alongside text transcripts in a single request. Which criterion is the deciding factor?", options:["Cost alone","Modality","Customizability","Latency alone"], correct:1,
   explain:"Needing to process both audio and text in one request requires a multimodal model — a modality requirement that rules out text-only models regardless of other factors."},
  {domain:D3, q:"A malicious user embeds hidden instructions inside a PDF that gets retrieved by a RAG system, attempting to override the assistant's behavior. What is this attack called?", options:["Overfitting","Prompt injection","Model drift","Data poisoning at inference time"], correct:1,
   explain:"Prompt injection is instructions smuggled into retrieved or user-supplied content, attempting to hijack the model's behavior — a Domain 3 and Domain 5 concern."},
  {domain:D3, q:"What is the main advantage of RAG's source attribution capability?", options:["It makes the model train faster","It allows tracing a specific answer back to the specific source documents that produced it","It eliminates the need for a vector database","It guarantees zero hallucination"], correct:1,
   explain:"Source attribution lets you trace a generated answer back to the specific retrieved documents, directly supporting transparency and explainability."},
  {domain:D3, q:"Retrieval returns 10 chunks, but only the top 2 are highly relevant, buried at positions 5 and 8. What technique would most directly address this?", options:["Increasing temperature","Re-ranking to move the most relevant chunks toward the start or end of the context","Reducing the embedding dimension","Disabling the vector database"], correct:1,
   explain:"Re-ranking reorders retrieved chunks by relevance, letting you place the strongest matches at the start or end where models attend most reliably — directly countering the lost-in-the-middle effect."}
);

EXAM_DATA.exam1.questions.push(
  {domain:D4, q:"A company publishes documentation describing a model's training data, intended use, and known limitations for all stakeholders. Which responsible AI dimension does this primarily support?", options:["Explainability","Transparency","Controllability","Safety"], correct:1,
   explain:"Transparency concerns the system as a whole being openly documented — training data, purpose, and limitations — applying to every output."},
  {domain:D4, q:"A loan-approval model's decision for one specific applicant is investigated using feature-attribution analysis to see why it was denied. Which dimension does this illustrate?", options:["Transparency","Explainability","Governance","Fairness"], correct:1,
   explain:"Explainability concerns a single output — why this particular decision happened — which feature-attribution analysis for one applicant directly addresses."},
  {domain:D4, q:"Which responsible AI dimension is most directly about preventing harmful system output and misuse?", options:["Safety","Controllability","Veracity and robustness","Governance"], correct:0,
   explain:"Safety is specifically about preventing harmful output and misuse, distinct from controllability (steering behavior) or robustness (reliability under adversarial input)."},
  {domain:D4, q:"A hiring model trained mostly on historical resumes from one demographic group underperforms for other groups. What is the most precise term for this issue?", options:["Measurement bias","Sampling bias","Algorithmic bias only","Label bias exclusively"], correct:1,
   explain:"The training data underrepresenting part of the real-world population is sampling bias, distinct from how a feature was measured or amplified by the algorithm."},
  {domain:D4, q:"Which AWS tool detects statistical bias in both a training dataset and a deployed model, and produces feature-attribution reports?", options:["Amazon Macie","SageMaker Clarify","AWS Config","Bedrock Guardrails"], correct:1,
   explain:"SageMaker Clarify is purpose-built for bias detection (pre- and post-training) and generating explainability reports."},
  {domain:D4, q:"A dataset's fraud labels were originally assigned using a flawed manual review process that consistently under-flagged one type of transaction. What kind of bias does this introduce?", options:["Sampling bias","Measurement bias","Algorithmic bias","No bias, since it was manual"], correct:1,
   explain:"Bias introduced by how a feature or label was measured or assigned — before the model ever sees the data — is measurement bias."},
  {domain:D4, q:"Which practice routes low-confidence or high-stakes model predictions to a human reviewer before acting on them?", options:["RLHF","Human-in-the-loop review","Chain-of-thought prompting","Fine-tuning"], correct:1,
   explain:"Human-in-the-loop review specifically routes uncertain or high-stakes predictions to a human before any automated action is taken."},
  {domain:D4, q:"What does AWS say about its named list of responsible AI dimensions over time?", options:["It is permanently fixed and will never change","AWS updates it over time as AI technology evolves","It only applies to SageMaker, not Bedrock","It has never changed since 2020"], correct:1,
   explain:"AWS explicitly states its core dimensions of responsible AI are reassessed and updated over time as AI technology evolves."},
  {domain:D4, q:"An AI Service Card published by AWS for Amazon Rekognition primarily supports which dimension?", options:["Controllability","Transparency","Safety exclusively","Governance exclusively"], correct:1,
   explain:"AI Service Cards document intended use cases and limitations at the service level, supporting transparency in the same way a model card does for a custom model."}
);

EXAM_DATA.exam1.questions.push(
  {domain:D5, q:"Under the shared responsibility model, who secures the physical data centers hosting a managed foundation model service?", options:["The customer","AWS","Both parties equally on every workload","A third-party auditor"], correct:1,
   explain:"AWS is responsible for security 'of' the cloud, including physical data center security. The customer is responsible for security 'in' the cloud."},
  {domain:D5, q:"A company must ensure only specific IAM roles can invoke a particular Bedrock model. What principle is this an application of?", options:["Data minimization","Least privilege","Purpose limitation","Data portability"], correct:1,
   explain:"Scoping exactly who can invoke a resource to only what's necessary is the principle of least privilege, implemented through IAM policies."},
  {domain:D5, q:"Which AWS service discovers and classifies sensitive data such as PII stored at rest in S3?", options:["Amazon Macie","AWS Config","Amazon Comprehend","CloudTrail"], correct:0,
   explain:"Amazon Macie is purpose-built to discover and classify sensitive data, including PII, in S3."},
  {domain:D5, q:"Which service provides an audit log of every API call, including which model was invoked and by whom?", options:["Amazon Macie","AWS CloudTrail","Amazon Comprehend","SageMaker Clarify"], correct:1,
   explain:"CloudTrail logs API activity across AWS services, forming the backbone of AI governance and incident investigation."},
  {domain:D5, q:"Under GDPR, which article grants an individual the right to have their personal data deleted?", options:["Article 5","Article 17","Article 20","Article 35"], correct:1,
   explain:"Article 17, the 'right to erasure,' is often called the right to be forgotten — distinct from Articles 5, 20, and 35."},
  {domain:D5, q:"Under GDPR, which article restricts decisions with legal or similarly significant effects made without meaningful human involvement?", options:["Article 5","Article 17","Article 22","Article 20"], correct:2,
   explain:"Article 22 restricts solely automated decision-making, including profiling, when it produces legal or similarly significant effects on an individual."},
  {domain:D5, q:"Before deploying a high-risk AI processing system under GDPR, what is typically required?", options:["A Data Protection Impact Assessment (Article 35)","Nothing beyond standard encryption","A patent filing","A separate business license in every EU country"], correct:0,
   explain:"Article 35 requires a Data Protection Impact Assessment before high-risk processing — many generative AI deployments qualify as high-risk."},
  {domain:D5, q:"A multi-tenant RAG chatbot must guarantee one customer's queries never surface another customer's documents. Where should this be enforced?", options:["Only via instructions in the final LLM prompt","As a metadata filter applied during the vector search itself","Only in Bedrock Guardrails","It is unnecessary if data is encrypted at rest"], correct:1,
   explain:"Access control for RAG must be enforced at retrieval time — a metadata filter scoped to the requesting user's permitted documents, applied during the vector search."},
  {domain:D5, q:"Which tool versions and catalogs deployed models, tracking lineage from data to deployed artifact?", options:["SageMaker Model Registry","Amazon Macie","AWS Config","Bedrock Guardrails"], correct:0,
   explain:"SageMaker Model Registry is the tool for versioning and cataloging models and tracking their lineage — the core of lifecycle governance."}
);

