EXAM_DATA.exam2.questions.push(
  {domain:D2, q:"Which statement correctly distinguishes a foundation model from a traditional task-specific model?", options:["Foundation models require labeled data exclusively","Foundation models are pre-trained broadly and adaptable to many tasks; traditional models are trained narrowly for one","There is no meaningful difference","Traditional models are always more accurate"], correct:1,
   explain:"Foundation models are pre-trained at scale on broad data, making them adaptable across many downstream tasks, unlike narrowly trained traditional models."},
  {domain:D2, q:"What does 'multi-head' attention refer to in the transformer architecture?", options:["Multiple models running on separate servers","Several parallel attention computations, each able to focus on different relationships","A model with multiple output layers only","Running inference multiple times and averaging results"], correct:1,
   explain:"Multi-head attention runs several attention computations in parallel, letting the model attend to different kinds of token relationships simultaneously."},
  {domain:D2, q:"A generation task wants more creative, varied output, willing to accept some unpredictability. Which parameter adjustment fits?", options:["Lower temperature","Higher temperature","Setting Top K to 1","Setting max tokens to 1"], correct:1,
   explain:"Higher temperature spreads the probability distribution, giving lower-probability tokens a real chance and producing more varied, creative output."},
  {domain:D2, q:"Top P is set to 0.5 for a distribution where the single top token already has 0.85 probability. What is the resulting nucleus?", options:["All tokens in the vocabulary","Just the single top token","Exactly two tokens","It depends only on temperature"], correct:1,
   explain:"Since the top token's probability (0.85) alone already exceeds the 0.5 threshold, the nucleus consists of just that one token."},
  {domain:D2, q:"Which statement about Top K and Top P is correct?", options:["Both always keep exactly the same number of tokens","Top K keeps a fixed count; Top P's count varies with the distribution's shape","Top P is applied before temperature always overrides both","Top K and Top P cannot be used together"], correct:1,
   explain:"Top K is a fixed-count filter. Top P's candidate count changes based on how concentrated or spread out the probability distribution is."},
  {domain:D2, q:"What is the purpose of a stop sequence in a generation request?", options:["It increases creativity","It immediately halts generation when the specified string is produced","It only affects training, not inference","It sets the temperature to zero"], correct:1,
   explain:"A stop sequence is a string that, once produced, immediately halts further generation — a length/output control, not a creativity control."},
  {domain:D2, q:"Why do context windows get measured in tokens rather than words?", options:["Tokens are always exactly one word","Tokens are sub-word units, and a word doesn't map cleanly to a fixed token count","Words are a technical term with no real meaning","Context windows are actually measured in characters"], correct:1,
   explain:"Since tokens are sub-word units (roughly three-quarters of a word on average in English), measuring in tokens is more precise than an imprecise word count."},
  {domain:D2, q:"A team evaluating a generated summary wants a metric robust to good paraphrasing that doesn't match the reference's exact wording. What should they use?", options:["Exact string match","BLEU","BERTScore","Word count comparison"], correct:2,
   explain:"BERTScore uses contextual embeddings to assess meaning rather than exact word overlap, making it robust to valid paraphrases."},
  {domain:D2, q:"What was one of the original stated motivations for introducing RAG, according to the technique's originating research?", options:["Reducing model hallucination and improving factual accuracy","Eliminating the need for foundation models entirely","Making models smaller","Replacing the need for tokenization"], correct:0,
   explain:"Reducing hallucination and improving factual grounding were among the original stated motivations for retrieval-augmented generation."},
  {domain:D2, q:"A company wants access to models from multiple providers through one consistent API, without managing GPU infrastructure. What should they use?", options:["Amazon SageMaker endpoints exclusively","Amazon Bedrock","Amazon EC2 directly","AWS Lambda alone"], correct:1,
   explain:"Bedrock provides a single managed API across multiple foundation model providers without requiring the customer to manage underlying infrastructure."},
  {domain:D2, q:"Which of the following best describes prompt engineering's relationship to a model's weights?", options:["It permanently changes the model's weights","It never changes the model's weights — it shapes output purely through input phrasing","It requires retraining after every prompt","It is identical to fine-tuning"], correct:1,
   explain:"Prompt engineering shapes model behavior entirely through how the input is written, with no changes to the underlying model weights."},
  {domain:D2, q:"What risk does non-determinism in generative AI output primarily create for applications?", options:["The same prompt can yield different outputs across calls, complicating testing and reproducibility","Models become incapable of generating text","It only affects image models","It eliminates the need for evaluation metrics"], correct:0,
   explain:"Non-determinism means identical prompts can produce different outputs run to run, which complicates automated testing and reproducibility of results."},
  {domain:D2, q:"A model card for a foundation model states its pre-training data cutoff date. Why does this matter operationally?", options:["It has no practical effect","It indicates the model may lack knowledge of events or information after that date","It sets the model's temperature automatically","It determines the context window size"], correct:1,
   explain:"A training data cutoff means the model's built-in knowledge doesn't include anything after that date — relevant for deciding when RAG is needed for current information."},
  {domain:D2, q:"Which best distinguishes ROUGE from BLEU?", options:["ROUGE is precision-oriented for translation; BLEU is recall-oriented for summarization","ROUGE is recall-oriented and used for summarization; BLEU is precision-oriented and used for translation","They are identical metrics with different names","Neither metric involves n-gram overlap"], correct:1,
   explain:"ROUGE is recall-oriented and standard for summarization evaluation; BLEU is precision-oriented (with a brevity penalty) and standard for translation evaluation."},
  {domain:D2, q:"A prompt requests 'answer in three sentences or less.' What kind of control is this, functionally?", options:["A runtime max-token parameter","An instruction-based length control achieving an effect similar to a max-token setting","A temperature adjustment","A stop sequence"], correct:1,
   explain:"Asking for a length constraint directly in the prompt is an instruction-based approach that achieves a similar effect to a max-token runtime parameter, without setting one."},
  {domain:D2, q:"What does perplexity generally measure in the context of a language model?", options:["How confidently a model predicts a sequence of text — lower perplexity indicates better predictive fit","The physical latency of a model's API response","The number of parameters in the model","The size of the model's context window"], correct:0,
   explain:"Perplexity measures how well a probability model predicts a sample; lower perplexity indicates the model finds the text less 'surprising,' generally reflecting better fit."}
);

EXAM_DATA.exam2.questions.push(
  {domain:D3, q:"A prompt asks the model to complete a task with no examples and only a plain instruction. What is this called?", options:["Few-shot prompting","Zero-shot prompting","Chain-of-thought prompting","Fine-tuning"], correct:1,
   explain:"Zero-shot prompting means asking the model to perform a task with no examples given, just a clear instruction."},
  {domain:D3, q:"A prompt explicitly states 'do not include any pricing information in your response.' What technique is this?", options:["Chain-of-thought prompting","Negative prompting","Few-shot prompting","RAG"], correct:1,
   explain:"Negative prompting explicitly states what to avoid in the output, as opposed to only specifying what to include."},
  {domain:D3, q:"A company needs a chatbot to cite the exact internal policy document backing each answer it gives. Which approach directly enables this?", options:["Fine-tuning alone","RAG, using its source-attribution capability","Increasing temperature","Chain-of-thought prompting alone"], correct:1,
   explain:"RAG's source-attribution capability lets a response be traced back to specific retrieved documents, directly enabling citation of the source policy."},
  {domain:D3, q:"A team wants a model to adopt an entirely new specialized writing style the base model doesn't produce well, and needs this permanently, without prompting for it every time. What's the best-fit approach?", options:["Prompt engineering only","RAG","Fine-tuning","Increasing the context window only"], correct:2,
   explain:"Teaching a new, persistent skill or style the base model doesn't do well is the classic use case for fine-tuning, which changes the model's weights."},
  {domain:D3, q:"In the RAG pipeline, what is the purpose of the 'augmented prompt' step?", options:["It replaces the user's original query entirely with retrieved text","It combines the original query with retrieved chunks before sending to the LLM","It fine-tunes the model on retrieved chunks","It re-ranks the vector database"], correct:1,
   explain:"The augmented prompt combines the original user query with the retrieved chunks, giving the LLM both the question and relevant source material."},
  {domain:D3, q:"Which knowledge base pattern relies purely on exact keyword or phrase matching against an index?", options:["Vector database search","Traditional/keyword search","Graph RAG","Hybrid search"], correct:1,
   explain:"Traditional or keyword search matches exact keywords or phrases against an index, unlike vector search which matches by semantic similarity."},
  {domain:D3, q:"Which Bedrock Knowledge Bases API returns only retrieved chunks, leaving the caller to build the prompt and call the model separately?", options:["RetrieveAndGenerate","Retrieve","InvokeModel","Converse"], correct:1,
   explain:"Retrieve returns just the relevant chunks; RetrieveAndGenerate performs retrieval, augmentation, and the LLM call together."},
  {domain:D3, q:"A team chunks documents at multiple granularities — sentence, paragraph, and section — retrieving at whichever level fits the query. What chunking strategy is this?", options:["Fixed-size chunking","Semantic chunking","Hierarchical chunking","No chunking at all"], correct:2,
   explain:"Hierarchical chunking splits documents at multiple granularities and retrieves at the appropriate level, handling both narrow and broad queries well."},
  {domain:D3, q:"A RAG system retrieves a large candidate set cheaply, then uses a more accurate model to re-score and reorder before the final LLM call. What is this technique called?", options:["Fixed-size chunking","Re-ranking","Fine-tuning","Prompt injection"], correct:1,
   explain:"Re-ranking retrieves a larger candidate set with a fast, cheap method, then re-scores it with a more accurate model before sending results to the LLM."},
  {domain:D3, q:"Why doesn't RAG fully eliminate hallucination risk, even with highly relevant retrieved context?", options:["RAG always increases hallucination","A model can still ignore or misread the retrieved context and generate ungrounded content","RAG only works for classification tasks","Retrieved context is never actually passed to the model"], correct:1,
   explain:"RAG reduces hallucination risk but doesn't eliminate it — a model can still fail to faithfully use correct context that's right in front of it."},
  {domain:D3, q:"What primarily distinguishes a Bedrock Agent from a basic RAG-powered chatbot?", options:["Agents cannot use a Knowledge Base","Agents can orchestrate multi-step tasks and call external APIs or functions to take action","Agents never require Guardrails","There is no real distinction"], correct:1,
   explain:"Bedrock Agents orchestrate multi-step workflows and can call APIs or Lambda functions to take real action, beyond just answering a single prompt."},
  {domain:D3, q:"An organization needs runtime filtering of harmful content and PII redaction applied consistently across multiple different foundation models. What should they use?", options:["Bedrock Guardrails","SageMaker Clarify","AWS Config","Amazon Kendra"], correct:0,
   explain:"Bedrock Guardrails provide runtime content filtering and PII redaction that applies independent of which underlying model is used."},
  {domain:D3, q:"A financial services task requires processing lengthy 300-page filings in a single request. Which model-selection criterion is the deciding constraint?", options:["Modality","Context window","Latency alone","Customizability alone"], correct:1,
   explain:"A model needs a large enough context window to fit the full document; this becomes the deciding factor regardless of other strengths."},
  {domain:D3, q:"A cost-sensitive batch summarization job runs overnight with no real-time requirement. Which criterion becomes relatively less important than for an interactive chat app?", options:["Cost","Latency","Accuracy","Context window"], correct:1,
   explain:"For an overnight batch job with no real-time requirement, latency matters far less than it would for a live interactive chat application."},
  {domain:D3, q:"A vector store returns 10 chunks for a query, but the single most relevant chunk lands at position 6. What risk does this create?", options:["No risk — position never matters","The most relevant chunk may be functionally under-attended to due to the 'lost in the middle' effect","The vector database will crash","Temperature will automatically compensate"], correct:1,
   explain:"Content in the middle of a long context tends to receive less reliable attention than content at the start or end — the 'lost in the middle' effect."},
  {domain:D3, q:"Which of the following is a genuine vector store option commonly paired with Bedrock Knowledge Bases when not using Managed Knowledge Bases?", options:["Amazon Polly","Aurora PostgreSQL with the pgvector extension","Amazon Transcribe","AWS CloudTrail"], correct:1,
   explain:"Aurora PostgreSQL with pgvector is a genuine self-managed vector store option, alongside OpenSearch Serverless, Pinecone, and MongoDB Atlas."},
  {domain:D3, q:"What is the primary purpose of top-k retrieval in a RAG pipeline?", options:["Filtering the model's output vocabulary","Selecting the k most similar chunks to return from the vector search","Setting the model's temperature","Determining the context window size"], correct:1,
   explain:"Top-k retrieval selects the k most similar chunks from the vector search results — k itself is a tuning knob affecting the retrieval/noise trade-off."},
  {domain:D3, q:"A company wants to reduce the cost of maintaining a self-hosted vector database while accepting less control over chunking and ranking. What should they consider?", options:["Bedrock Managed Knowledge Bases","Fine-tuning the base model instead","Increasing Top K to maximum","Disabling retrieval entirely"], correct:0,
   explain:"Managed Knowledge Bases trade fine-grained control over chunking and ranking for lower operational cost and complexity — matching this exact trade-off."}
);

EXAM_DATA.exam2.questions.push(
  {domain:D4, q:"Which responsible AI dimension concerns achieving correct outputs reliably, even under unexpected or adversarial input?", options:["Fairness","Veracity and robustness","Governance","Transparency"], correct:1,
   explain:"Veracity and robustness specifically concerns correct, reliable outputs even under unexpected or adversarial conditions."},
  {domain:D4, q:"A company implements organization-wide processes to define, enforce, and audit responsible AI practices across every team. Which dimension does this represent?", options:["Governance","Explainability","Safety","Controllability"], correct:0,
   explain:"Governance is the organizational-process dimension — defining, implementing, and enforcing responsible AI practices company-wide."},
  {domain:D4, q:"A published model card documents a model's training data and known limitations for external stakeholders. This is a practical example of which dimension?", options:["Explainability","Transparency","Controllability","Safety"], correct:1,
   explain:"A model card documents the system as a whole for stakeholders — the defining trait of transparency, as opposed to explaining one specific output."},
  {domain:D4, q:"A model's individual prediction is analyzed using SHAP values to show which input features drove that specific outcome. This is a practical example of which dimension?", options:["Transparency","Explainability","Governance","Fairness"], correct:1,
   explain:"Explaining why one specific output occurred, via feature attribution for that instance, is explainability — distinct from system-wide transparency."},
  {domain:D4, q:"A model consistently produces lower accuracy for a demographic underrepresented in its training set. What kind of bias is most likely responsible?", options:["Measurement bias","Sampling bias","Algorithmic bias exclusively","No bias — this is expected behavior"], correct:1,
   explain:"Underrepresentation of a group in the training data relative to the real-world population is sampling bias."},
  {domain:D4, q:"Which AWS tool would a team use specifically to generate feature-attribution explainability reports for a deployed model?", options:["SageMaker Clarify","Amazon Macie","AWS Config","Amazon Comprehend"], correct:0,
   explain:"SageMaker Clarify generates feature-attribution explainability reports in addition to bias detection, matching this exact requirement."},
  {domain:D4, q:"Which responsible AI dimension is most directly about having mechanisms to monitor and steer a deployed AI system's ongoing behavior?", options:["Controllability","Fairness","Privacy and security","Veracity and robustness"], correct:0,
   explain:"Controllability specifically means having real mechanisms to monitor and steer system behavior after deployment, not just at design time."},
  {domain:D4, q:"A team routes any AI-generated medical recommendation to a licensed clinician for review before it reaches a patient. What responsible AI practice does this represent?", options:["Fine-tuning","Human-in-the-loop review","Chain-of-thought prompting","RAG source attribution"], correct:1,
   explain:"Routing high-stakes predictions to a human reviewer before any action is taken is human-in-the-loop review."},
  {domain:D4, q:"Why should a candidate treat AWS's current list of responsible AI dimensions as subject to change?", options:["AWS has stated it updates this list over time as AI technology evolves","The list is only a marketing document with no technical basis","The dimensions are randomly generated","AWS has never revised this list before"], correct:0,
   explain:"AWS explicitly states this list is reassessed and updated as AI technology evolves — worth treating as current rather than permanently fixed."}
);

EXAM_DATA.exam2.questions.push(
  {domain:D5, q:"Under the shared responsibility model, who is responsible for classifying data and deciding what gets sent to a foundation model?", options:["AWS exclusively","The customer","Neither party — this is automated","A third-party compliance vendor"], correct:1,
   explain:"AWS secures the underlying infrastructure, but the customer remains responsible for data classification and what actually gets sent to a model."},
  {domain:D5, q:"Which AWS service can identify and redact PII directly within text content, useful ahead of embedding it in a RAG pipeline?", options:["Amazon Comprehend PII detection","AWS Config","Amazon Macie","SageMaker Model Registry"], correct:0,
   explain:"Amazon Comprehend's PII detection identifies and can redact PII within text content, distinct from Macie which scans data at rest in S3."},
  {domain:D5, q:"Which practice ensures traffic to a Bedrock or SageMaker endpoint never traverses the public internet?", options:["VPC endpoints","CloudTrail logging","GDPR Article 35","AWS Config rules"], correct:0,
   explain:"VPC endpoints keep model traffic within the AWS network, off the public internet, for workloads with strict network isolation requirements."},
  {domain:D5, q:"Under GDPR, which article covers an individual's right to obtain and reuse their own data across different services?", options:["Article 5","Article 17","Article 20","Article 22"], correct:2,
   explain:"Article 20 covers data portability — the right for individuals to obtain and reuse their data across services."},
  {domain:D5, q:"Which GDPR principle, from Article 5, requires collecting only the data actually necessary for a stated purpose?", options:["Data minimization","Data portability","Right to erasure","Automated decision-making restriction"], correct:0,
   explain:"Data minimization, one of the Article 5 core principles, requires collecting only what's necessary for the stated purpose."},
  {domain:D5, q:"A multi-tenant RAG system enforces document access using a metadata filter scoped to each user, applied during the vector search. What does this prevent?", options:["Slow query performance only","One customer's queries from ever surfacing another customer's documents, regardless of similarity score","The need for encryption","The need for IAM policies"], correct:1,
   explain:"Applying an ownership filter during the vector search ensures unauthorized chunks never become retrieval candidates at all, regardless of how similar they score."},
  {domain:D5, q:"Which tool tracks configuration changes to AI-related AWS resources over time for compliance auditing?", options:["AWS Config","Amazon Polly","Amazon Lex","SageMaker Ground Truth"], correct:0,
   explain:"AWS Config tracks configuration changes to resources over time, supporting compliance auditing — distinct from CloudTrail's API call logging."},
  {domain:D5, q:"Encryption at rest for data used in a Bedrock knowledge base is typically managed through which AWS capability?", options:["AWS KMS","Amazon Polly","Amazon Lex","SageMaker Autopilot"], correct:0,
   explain:"AWS Key Management Service (KMS) is used to manage encryption keys for data at rest across AWS services, including S3 and Bedrock-related storage."},
  {domain:D5, q:"A company wants version history and lineage tracking for every model it deploys, from training data to production artifact. What should it use?", options:["SageMaker Model Registry","Amazon Macie","Amazon Comprehend","AWS CloudTrail alone"], correct:0,
   explain:"SageMaker Model Registry is specifically built for versioning and cataloging models with lineage tracking, the core governance tool for this need."}
);
